/**
 * Niños print queue (odd/tasks/ninos-checkin-pco.md, S10, S6; T3a). The
 * database builds the labels after a check-in
 * (20261109100000_ninos_impresion.sql) and a print agent claims them through
 * /api/ninos/impresion/agente with its station token
 * (docs/ninos/impresion.md). These helpers read the agent's Bearer token (64
 * hex chars, generated by the database and stored only as its sha256),
 * compare hashes in constant time, parse the route bodies (a reprint needs a
 * reason) and enqueue the labels of a check-in without ever failing it.
 */
import { createHash, timingSafeEqual } from 'node:crypto'

const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i
const ISO_DATE = /^\d{4}-\d{2}-\d{2}$/
const TOKEN = /^[0-9a-f]{64}$/
const MAX_ERROR = 300
const MAX_NOTA = 200

type Objeto = Record<string, unknown>
const esObjeto = (v: unknown): v is Objeto => typeof v === 'object' && v !== null && !Array.isArray(v)
const esUuid = (v: unknown): v is string => typeof v === 'string' && UUID.test(v)

/**
 * Payload of a child label (kept small: no phone, cédula, allergy text nor
 * custody). visita: 'primera' with no earlier check-in date, 'visitante' in
 * visits 2–3, null for a regular (S9.3).
 */
export type EtiquetaNino = {
  nombre: string
  apellido: string
  codigo: string
  salon: string
  area: string
  alergias: boolean
  visita: 'primera' | 'visitante' | null
  fecha: string
  servicio: string
  hora: string
}

/** Payload of the parent receipt: one per family visit (código); never the salón. */
export type EtiquetaRepresentante = {
  codigo: string
  ninos: string[]
  areas: string[]
  fecha: string
  servicio: string
  hora: string
}

export type TrabajoImpresion =
  | { id: string; tipo: 'nino'; payload: EtiquetaNino; intentos: number; created_at: string }
  | { id: string; tipo: 'representante'; payload: EtiquetaRepresentante; intentos: number; created_at: string }

/** Label size in mm; null until the roll is measured. */
export type EstacionAgente = { id: string; nombre: string; ancho_mm: number | null; alto_mm: number | null; dpi: number }

export type ReporteImpresion = { id: string; estado: 'impresa' | 'error'; error: string | null }

export type TipoReimpresion = 'todas' | 'representante' | 'nino'

/** S10 reprint reasons: se trabó, se perdió, otro (otro needs a note). */
export const MOTIVOS_REIMPRESION = ['se_trabo', 'se_perdio', 'otro'] as const
export type MotivoReimpresion = (typeof MOTIVOS_REIMPRESION)[number]

export type EntradaReimpresion = {
  estacionId: string
  turnoId: string
  fecha: string
  codigo: string
  tipo: TipoReimpresion
  ninoId: string | null
  motivo: MotivoReimpresion
  nota: string | null
}

export function tokenDeAutorizacion(header: string | null): string | null {
  const m = /^Bearer\s+(\S+)\s*$/i.exec(header ?? '')
  return m && TOKEN.test(m[1]) ? m[1] : null
}

export function hashToken(token: string): string {
  return createHash('sha256').update(token, 'utf8').digest('hex')
}

export function hashesIguales(esperado: string, recibido: unknown): boolean {
  if (typeof recibido !== 'string') return false
  const a = Buffer.from(esperado, 'utf8')
  const b = Buffer.from(recibido, 'utf8')
  return a.length === b.length && timingSafeEqual(a, b)
}

/** Jobs per claim: ?max= of the agent, 1–20, 10 by default. */
export function maxTrabajos(param: string | null): number {
  const n = Number.parseInt(param ?? '', 10)
  return Number.isNaN(n) ? 10 : Math.min(Math.max(n, 1), 20)
}

export function parseReporte(body: unknown): ReporteImpresion | null {
  if (!esObjeto(body) || !esUuid(body.id)) return null
  if (body.estado !== 'impresa' && body.estado !== 'error') return null
  if (body.error !== undefined && body.error !== null && typeof body.error !== 'string') return null
  const error = typeof body.error === 'string' ? body.error.trim().slice(0, MAX_ERROR) : ''
  return { id: body.id, estado: body.estado, error: error || null }
}

export function parseReimpresion(body: unknown): EntradaReimpresion | null {
  if (!esObjeto(body)) return null
  const { estacionId, turnoId, fecha, codigo, tipo } = body
  const ninoId = body.ninoId ?? null
  if (!esUuid(estacionId) || !esUuid(turnoId) || typeof fecha !== 'string' || !ISO_DATE.test(fecha)) return null
  if (typeof codigo !== 'string' || !/^\d{3,4}$/.test(codigo)) return null
  if (tipo !== 'todas' && tipo !== 'representante' && tipo !== 'nino') return null
  if (tipo === 'nino' ? !esUuid(ninoId) : ninoId !== null) return null
  const { motivo } = body
  if (!(MOTIVOS_REIMPRESION as readonly unknown[]).includes(motivo)) return null
  if (body.nota !== undefined && body.nota !== null && typeof body.nota !== 'string') return null
  const nota = typeof body.nota === 'string' ? body.nota.trim() : ''
  if (nota.length > MAX_NOTA || (motivo === 'otro' && !nota)) return null
  return {
    estacionId, turnoId, fecha, codigo, tipo, ninoId: ninoId as string | null,
    motivo: motivo as MotivoReimpresion, nota: nota || null,
  }
}

/** The desk's station in the check-in body; anything else means "no printing". */
export function estacionDeCheckin(body: unknown): string | null {
  return esObjeto(body) && esUuid(body.estacionId) ? body.estacionId : null
}

/** What the agent receives: the label size and the jobs, never the token hash. */
export function respuestaAgente(
  estacion: Objeto,
  trabajos: unknown,
): { estacion: EstacionAgente; trabajos: TrabajoImpresion[] } {
  const mm = (v: unknown) => (v === null || v === undefined ? null : Number(v))
  return {
    estacion: {
      id: String(estacion.id),
      nombre: String(estacion.nombre),
      ancho_mm: mm(estacion.ancho_mm),
      alto_mm: mm(estacion.alto_mm),
      dpi: Number(estacion.dpi),
    },
    trabajos: Array.isArray(trabajos) ? (trabajos as TrabajoImpresion[]) : [],
  }
}

/** RPC messages of the print queue: fixed codes (never data), safe to send back. */
export const ERRORES_IMPRESION = [
  'sin_autoridad',
  'datos_invalidos',
  'estacion_no_encontrada',
  'estacion_inactiva',
  'checkin_no_encontrado',
  'trabajo_no_encontrado',
] as const

export function errorImpresion(error: { code?: string; message?: string }): { code?: string; message?: string } {
  const message = (error.message ?? '').trim()
  return (ERRORES_IMPRESION as readonly string[]).includes(message) ? { code: error.code, message } : { code: error.code }
}

type Rpc = (nombre: string, args: Record<string, unknown>) => PromiseLike<{ data: unknown; error: { code?: string } | null }>

/**
 * Queues the labels of a check-in as the desk user. Best effort: printing
 * never fails nor delays the ingreso (the código is on screen and on the
 * parent's phone), so every failure is only logged, by code.
 */
export async function encolarEtiquetas(
  rpc: Rpc,
  e: { estacionId: string; turnoId: string; fecha: string; ninoIds: string[] },
): Promise<void> {
  try {
    const { error } = await rpc('ninos_impresion_encolar', {
      p_estacion_id: e.estacionId,
      p_turno_id: e.turnoId,
      p_fecha: e.fecha,
      p_nino_ids: e.ninoIds,
    })
    if (error) console.error('[ninos/impresion] no se encolaron las etiquetas:', error.code ?? 'sin código')
  } catch (err) {
    console.error('[ninos/impresion] no se encolaron las etiquetas:', err instanceof Error ? err.name : 'desconocido')
  }
}
